final readonly class MeetingService
{
    public function __construct(private PDO $pdo){}

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function schedule(string $organisationId,string $userId,string $role,array $input):array
    {
        $this->assertWriter($organisationId,$userId,$role);
        $projectId=$this->id($input['projectId']??null,'meeting_project_required');
        $this->project($organisationId,$projectId);
        $title=$this->text($input['title']??null,220,'meeting_title_required');
        $type=$this->text($input['meetingType']??null,80,'meeting_type_required');
        $phase=$this->text($input['phase']??null,60,'meeting_phase_required');
        if(ProjectPhase::tryFrom($phase)===null)throw new MeetingException('meeting_phase_invalid');
        try{$startsAt=(new DateTimeImmutable($this->text($input['startsAt']??null,40,'meeting_start_required')))->format('Y-m-d H:i:s.u');}catch(Throwable){throw new MeetingException('meeting_start_invalid');}
        $duration=(int)($input['durationMinutes']??0);if($duration<5||$duration>1440)throw new MeetingException('meeting_duration_invalid');
        $agenda=$this->agenda($input['agenda']??null);$attendees=$this->attendees($input['attendees']??null);$policy=$this->policy($input['policy']??null);
        $id=Identifier::generate();
        $this->pdo->beginTransaction();
        try{$statement=$this->pdo->prepare("INSERT INTO governed_meetings(id,organisation_id,project_id,title,meeting_type,phase,starts_at,duration_minutes,agenda,attendees,policy,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),:title,:meeting_type,:phase,:starts_at,:duration,:agenda,:attendees,:policy,UNHEX(:created_by))");$statement->execute(['id'=>$id,'organisation_id'=>$organisationId,'project_id'=>$projectId,'title'=>$title,'meeting_type'=>$type,'phase'=>$phase,'starts_at'=>$startsAt,'duration'=>$duration,'agenda'=>$this->json($agenda),'attendees'=>$this->json($attendees),'policy'=>$this->json($policy),'created_by'=>$userId]);(new AuditService($this->pdo))->append($organisationId,$userId,'meeting.scheduled','governed_meeting',$id,['projectId'=>$projectId,'startsAt'=>$startsAt,'policy'=>$policy]);$this->pdo->commit();return $this->get($organisationId,$userId,$id);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function recordConsent(string $organisationId,string $userId,string $role,string $meetingId,string $identity,bool $consented):array
    {
        $this->assertWriter($organisationId,$userId,$role);$identity=$this->text($identity,320,'meeting_attendee_identity_required');$meeting=$this->meeting($organisationId,$meetingId,false);
        $attendees=json_decode((string)$meeting['attendees'],true,64,JSON_THROW_ON_ERROR);if(!in_array(strtolower($identity),array_map(static fn(array $a):string=>strtolower((string)$a['identity']),$attendees),true))throw new MeetingException('meeting_attendee_not_found');
        $this->pdo->beginTransaction();
        try{$statement=$this->pdo->prepare('INSERT INTO meeting_consents(id,meeting_id,attendee_identity,consented,recorded_by) VALUES(UNHEX(:id),UNHEX(:meeting_id),:identity,:consented,UNHEX(:recorded_by)) ON DUPLICATE KEY UPDATE consented=VALUES(consented),recorded_by=VALUES(recorded_by),recorded_at=UTC_TIMESTAMP(6)');$statement->execute(['id'=>Identifier::generate(),'meeting_id'=>$meetingId,'identity'=>$identity,'consented'=>$consented?1:0,'recorded_by'=>$userId]);(new AuditService($this->pdo))->append($organisationId,$userId,'meeting.consent_recorded','governed_meeting',$meetingId,['attendeeIdentity'=>$identity,'consented'=>$consented]);$this->pdo->commit();return $this->get($organisationId,$userId,$meetingId);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    /** @return array<string,mixed> */
    public function start(string $organisationId,string $userId,string $role,string $meetingId):array
    {
        $this->assertWriter($organisationId,$userId,$role);$this->pdo->beginTransaction();
        try{$meeting=$this->meeting($organisationId,$meetingId,true);if($meeting['status']!=='scheduled')throw new MeetingException('meeting_not_scheduled');$policy=json_decode((string)$meeting['policy'],true,64,JSON_THROW_ON_ERROR);if(($policy['consentRequired']??false)&&(($policy['recordingRequested']??false)||($policy['transcriptionRequested']??false))){$attendees=json_decode((string)$meeting['attendees'],true,64,JSON_THROW_ON_ERROR);$s=$this->pdo->prepare('SELECT attendee_identity FROM meeting_consents WHERE meeting_id=UNHEX(:id) AND consented=1');$s->execute(['id'=>$meetingId]);$consented=array_map('strtolower',$s->fetchAll(PDO::FETCH_COLUMN));foreach($attendees as $attendee)if(!in_array(strtolower((string)$attendee['identity']),$consented,true))throw new MeetingException('meeting_consent_incomplete');}$this->pdo->prepare("UPDATE governed_meetings SET status='live',started_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id)")->execute(['id'=>$meetingId]);(new AuditService($this->pdo))->append($organisationId,$userId,'meeting.started','governed_meeting',$meetingId,['recording'=>$policy['recordingRequested'],'transcription'=>$policy['transcriptionRequested']]);$this->pdo->commit();return $this->get($organisationId,$userId,$meetingId);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function conclude(string $organisationId,string $userId,string $role,string $meetingId,array $input):array
    {
        $this->assertWriter($organisationId,$userId,$role);$transcript=$this->transcript($input['transcript']??null);$minutes=$this->minutes($input['minutes']??null);$outcomes=$this->outcomes($input['outcomes']??null);$this->pdo->beginTransaction();
        try{$meeting=$this->meeting($organisationId,$meetingId,true);if($meeting['status']!=='live')throw new MeetingException('meeting_not_live');$minutesId=Identifier::generate();$s=$this->pdo->prepare("INSERT INTO governed_meeting_minutes(id,meeting_id,revision,transcript,minutes_content,outcomes) VALUES(UNHEX(:id),UNHEX(:meeting_id),1,:transcript,:minutes,:outcomes)");$s->execute(['id'=>$minutesId,'meeting_id'=>$meetingId,'transcript'=>$this->json($transcript),'minutes'=>$this->json($minutes),'outcomes'=>$this->json($outcomes)]);$this->pdo->prepare("UPDATE governed_meetings SET status='review_required',concluded_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id)")->execute(['id'=>$meetingId]);(new AuditService($this->pdo))->append($organisationId,$userId,'meeting.review_created','governed_meeting',$meetingId,['minutesId'=>$minutesId,'outcomeCount'=>count($outcomes)]);$this->pdo->commit();return $this->get($organisationId,$userId,$meetingId);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function reviewOutcome(string $organisationId,string $userId,string $role,string $meetingId,int $index,string $state,string $reason):array
    {
        $this->assertWriter($organisationId,$userId,$role);if(!in_array($state,['accepted','rejected'],true))throw new MeetingException('meeting_outcome_state_invalid');$reason=$this->text($reason,500,'meeting_outcome_reason_required');$this->pdo->beginTransaction();
        try{$meeting=$this->meeting($organisationId,$meetingId,true);if($meeting['status']!=='review_required')throw new MeetingException('meeting_not_in_review');$minutes=$this->draftMinutes($meetingId,true);$outcomes=json_decode((string)$minutes['outcomes'],true,64,JSON_THROW_ON_ERROR);if(!isset($outcomes[$index]))throw new MeetingException('meeting_outcome_not_found');$outcomes[$index]['state']=$state;$outcomes[$index]['reviewReason']=$reason;$outcomes[$index]['reviewedBy']=$userId;$outcomes[$index]['reviewedAt']=(new DateTimeImmutable())->format('Y-m-d\TH:i:s.u\Z');$this->pdo->prepare('UPDATE governed_meeting_minutes SET outcomes=:outcomes WHERE id=UNHEX(:id)')->execute(['outcomes'=>$this->json($outcomes),'id'=>$minutes['id']]);(new AuditService($this->pdo))->append($organisationId,$userId,'meeting.outcome_reviewed','governed_meeting',$meetingId,['outcomeIndex'=>$index,'state'=>$state,'reason'=>$reason]);$this->pdo->commit();return $this->get($organisationId,$userId,$meetingId);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    /** @param array<string,mixed> $approval @return array<string,mixed> */
    public function publishMinutes(string $organisationId,string $userId,string $role,string $meetingId,array $approval):array
    {
        $this->assertWriter($organisationId,$userId,$role);if(($approval['reviewerConfirmed']??false)!==true)throw new MeetingException('meeting_reviewer_confirmation_required');$reason=$this->text($approval['publishReason']??null,500,'meeting_publish_reason_required');$this->pdo->beginTransaction();
        try{$meeting=$this->meeting($organisationId,$meetingId,true);if(!in_array($meeting['status'],['review_required','published'],true))throw new MeetingException('meeting_not_in_review');$minutes=$this->draftMinutes($meetingId,true);$outcomes=json_decode((string)$minutes['outcomes'],true,64,JSON_THROW_ON_ERROR);foreach($outcomes as $outcome)if(!in_array($outcome['state']??'pending',['accepted','rejected'],true))throw new MeetingException('meeting_outcomes_pending');$snapshot=['meeting'=>['id'=>$meetingId,'title'=>$meeting['title'],'projectId'=>$meeting['project_id'],'startsAt'=>$meeting['starts_at'],'agenda'=>json_decode((string)$meeting['agenda'],true,64,JSON_THROW_ON_ERROR),'attendees'=>json_decode((string)$meeting['attendees'],true,64,JSON_THROW_ON_ERROR),'policy'=>json_decode((string)$meeting['policy'],true,64,JSON_THROW_ON_ERROR)],'revision'=>(int)$minutes['revision'],'transcript'=>json_decode((string)$minutes['transcript'],true,64,JSON_THROW_ON_ERROR),'minutes'=>json_decode((string)$minutes['minutes_content'],true,64,JSON_THROW_ON_ERROR),'outcomes'=>$outcomes,'publication'=>['reviewedBy'=>$userId,'reason'=>$reason]];$hash=hash('sha256',$this->json($snapshot));$this->pdo->prepare("UPDATE governed_meeting_minutes SET status='published',publication_reason=:reason,audit_hash=:hash,reviewed_by=UNHEX(:user_id),published_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id)")->execute(['reason'=>$reason,'hash'=>$hash,'user_id'=>$userId,'id'=>$minutes['id']]);if(is_string($minutes['supersedes_id']))$this->pdo->prepare("UPDATE governed_meeting_minutes SET status='superseded' WHERE id=UNHEX(:id)")->execute(['id'=>$minutes['supersedes_id']]);$this->pdo->prepare("UPDATE governed_meetings SET status='published' WHERE id=UNHEX(:id)")->execute(['id'=>$meetingId]);$write=$this->pdo->prepare('INSERT INTO meeting_outcome_writebacks(id,organisation_id,project_id,meeting_id,minutes_id,outcome_index,outcome_type,destination,payload) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:meeting_id),UNHEX(:minutes_id),:outcome_index,:outcome_type,:destination,:payload)');foreach($outcomes as $index=>$outcome)if(($outcome['state']??null)==='accepted')$write->execute(['id'=>Identifier::generate(),'organisation_id'=>$organisationId,'project_id'=>$meeting['project_id'],'meeting_id'=>$meetingId,'minutes_id'=>$minutes['id'],'outcome_index'=>$index,'outcome_type'=>$outcome['type'],'destination'=>$outcome['destination'],'payload'=>$this->json($outcome)]);(new ProjectRecordService($this->pdo))->issue(new ProjectContext($organisationId,$userId,(string)$meeting['project_id'],$role),ProjectPhase::from((string)$meeting['phase']),'meetings','meeting_minutes',(string)$meeting['title'].' · minutes revision '.$minutes['revision'],'issued',['meetingId'=>$meetingId,'minutesId'=>$minutes['id'],'revision'=>(int)$minutes['revision'],'auditHash'=>$hash,'snapshot'=>$snapshot],['required'=>true,'reviewedBy'=>$userId]);(new AuditService($this->pdo))->append($organisationId,$userId,'meeting.minutes_published','governed_meeting',$meetingId,['minutesId'=>$minutes['id'],'revision'=>(int)$minutes['revision'],'auditHash'=>$hash,'acceptedWritebacks'=>count(array_filter($outcomes,static fn(array $o):bool=>($o['state']??null)==='accepted'))]);$this->pdo->commit();return $this->get($organisationId,$userId,$meetingId);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    /** @return array<string,mixed> */
    public function correctMinutes(string $organisationId,string $userId,string $role,string $meetingId,string $reason):array
    {
        $this->assertWriter($organisationId,$userId,$role);$reason=$this->text($reason,500,'meeting_correction_reason_required');$this->pdo->beginTransaction();
        try{$meeting=$this->meeting($organisationId,$meetingId,true);if($meeting['status']!=='published')throw new MeetingException('meeting_minutes_not_published');$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,revision,transcript,minutes_content,outcomes FROM governed_meeting_minutes WHERE meeting_id=UNHEX(:meeting_id) AND status='published' ORDER BY revision DESC LIMIT 1 FOR UPDATE");$s->execute(['meeting_id'=>$meetingId]);$previous=$s->fetch();if(!is_array($previous))throw new MeetingException('meeting_minutes_not_found');$id=Identifier::generate();$revision=(int)$previous['revision']+1;$this->pdo->prepare('INSERT INTO governed_meeting_minutes(id,meeting_id,supersedes_minutes_id,revision,transcript,minutes_content,outcomes,correction_reason) VALUES(UNHEX(:id),UNHEX(:meeting_id),UNHEX(:supersedes_id),:revision,:transcript,:minutes,:outcomes,:reason)')->execute(['id'=>$id,'meeting_id'=>$meetingId,'supersedes_id'=>$previous['id'],'revision'=>$revision,'transcript'=>$previous['transcript'],'minutes'=>$previous['minutes_content'],'outcomes'=>$previous['outcomes'],'reason'=>$reason]);(new AuditService($this->pdo))->append($organisationId,$userId,'meeting.minutes_correction_created','governed_meeting',$meetingId,['minutesId'=>$id,'supersedesMinutesId'=>$previous['id'],'revision'=>$revision,'reason'=>$reason]);$this->pdo->commit();return $this->minutesById($id);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    /** @return array<string,mixed> */
    public function get(string $organisationId,string $userId,string $meetingId):array
    {
        $this->assertMember($organisationId,$userId);$row=$this->meeting($organisationId,$meetingId,false);$result=['id'=>$row['id'],'projectId'=>$row['project_id'],'title'=>$row['title'],'meetingType'=>$row['meeting_type'],'phase'=>$row['phase'],'status'=>$row['status'],'startsAt'=>$row['starts_at'],'durationMinutes'=>(int)$row['duration_minutes'],'agenda'=>json_decode((string)$row['agenda'],true,64,JSON_THROW_ON_ERROR),'attendees'=>json_decode((string)$row['attendees'],true,64,JSON_THROW_ON_ERROR),'policy'=>json_decode((string)$row['policy'],true,64,JSON_THROW_ON_ERROR),'startedAt'=>$row['started_at'],'concludedAt'=>$row['concluded_at']];$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id FROM governed_meeting_minutes WHERE meeting_id=UNHEX(:meeting_id) AND status=:status ORDER BY revision DESC LIMIT 1");$s->execute(['meeting_id'=>$meetingId,'status'=>$row['status']==='published'?'published':'draft']);$id=$s->fetchColumn();$result['minutes']=is_string($id)?$this->minutesById($id):null;return $result;
    }

    /** @return list<array<string,mixed>> */
    public function list(string $organisationId,string $userId,?string $projectId=null):array{$this->assertMember($organisationId,$userId);$sql='SELECT LOWER(HEX(id)) id FROM governed_meetings WHERE organisation_id=UNHEX(:organisation_id)'.($projectId!==null?' AND project_id=UNHEX(:project_id)':'').' ORDER BY starts_at DESC,id';$s=$this->pdo->prepare($sql);$params=['organisation_id'=>$organisationId];if($projectId!==null)$params['project_id']=$projectId;$s->execute($params);return array_map(fn(string $id):array=>$this->get($organisationId,$userId,$id),$s->fetchAll(PDO::FETCH_COLUMN));}

    /** @return array<string,mixed> */
    private function meeting(string $organisationId,string $meetingId,bool $lock):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,title,meeting_type,phase,status,starts_at,duration_minutes,agenda,attendees,policy,started_at,concluded_at FROM governed_meetings WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)".($lock?' FOR UPDATE':''));$s->execute(['id'=>$meetingId,'organisation_id'=>$organisationId]);$row=$s->fetch();if(!is_array($row))throw new MeetingException('meeting_not_found');return $row;}
    /** @return array<string,mixed> */
    private function draftMinutes(string $meetingId,bool $lock):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(supersedes_minutes_id)) supersedes_id,revision,transcript,minutes_content,outcomes FROM governed_meeting_minutes WHERE meeting_id=UNHEX(:meeting_id) AND status='draft' ORDER BY revision DESC LIMIT 1".($lock?' FOR UPDATE':''));$s->execute(['meeting_id'=>$meetingId]);$row=$s->fetch();if(!is_array($row))throw new MeetingException('meeting_minutes_not_found');return $row;}
    /** @return array<string,mixed> */
    private function minutesById(string $id):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,LOWER(HEX(supersedes_minutes_id)) supersedesMinutesId,revision,status,transcript,minutes_content,outcomes,correction_reason correctionReason,publication_reason publicationReason,audit_hash auditHash,published_at publishedAt FROM governed_meeting_minutes WHERE id=UNHEX(:id)');$s->execute(['id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new MeetingException('meeting_minutes_not_found');$r['revision']=(int)$r['revision'];$r['transcript']=json_decode((string)$r['transcript'],true,64,JSON_THROW_ON_ERROR);$r['content']=json_decode((string)$r['minutes_content'],true,64,JSON_THROW_ON_ERROR);$r['outcomes']=json_decode((string)$r['outcomes'],true,64,JSON_THROW_ON_ERROR);unset($r['minutes_content']);return$r;}
    private function project(string $organisationId,string $projectId):void{$s=$this->pdo->prepare('SELECT 1 FROM projects WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$s->execute(['id'=>$projectId,'organisation_id'=>$organisationId]);if($s->fetchColumn()===false)throw new MeetingException('meeting_project_not_found');}
    /** @return list<array{title:string,owner:string,minutes:int}> */
    private function agenda(mixed $value):array{if(!is_array($value)||$value===[])throw new MeetingException('meeting_agenda_required');$out=[];foreach($value as $item){if(!is_array($item))throw new MeetingException('meeting_agenda_invalid');$minutes=(int)($item['minutes']??0);if($minutes<1||$minutes>480)throw new MeetingException('meeting_agenda_invalid');$out[]=['title'=>$this->text($item['title']??null,220,'meeting_agenda_invalid'),'owner'=>$this->text($item['owner']??null,180,'meeting_agenda_invalid'),'minutes'=>$minutes];}return$out;}
    /** @return list<array{identity:string,role:string}> */
    private function attendees(mixed $value):array{if(!is_array($value)||$value===[])throw new MeetingException('meeting_attendees_required');$out=[];foreach($value as $item){if(!is_array($item))throw new MeetingException('meeting_attendee_invalid');$out[]=['identity'=>$this->text($item['identity']??null,320,'meeting_attendee_invalid'),'role'=>$this->text($item['role']??null,60,'meeting_attendee_invalid')];}return$out;}
    /** @return array<string,mixed> */
    private function policy(mixed $value):array{if(!is_array($value))throw new MeetingException('meeting_policy_required');$retention=(int)($value['retentionDays']??0);if($retention<1||$retention>3650)throw new MeetingException('meeting_retention_invalid');$confidentiality=$this->text($value['confidentiality']??null,80,'meeting_confidentiality_required');return['recordingRequested'=>($value['recordingRequested']??false)===true,'transcriptionRequested'=>($value['transcriptionRequested']??false)===true,'consentRequired'=>($value['consentRequired']??true)===true,'retentionDays'=>$retention,'confidentiality'=>$confidentiality];}
    /** @return list<array<string,mixed>> */
    private function transcript(mixed $value):array{if(!is_array($value)||$value===[])throw new MeetingException('meeting_transcript_required');return array_map(fn($x)=>is_array($x)?['time'=>$this->text($x['time']??null,20,'meeting_transcript_invalid'),'speaker'=>$this->text($x['speaker']??null,180,'meeting_transcript_invalid'),'text'=>$this->text($x['text']??null,4000,'meeting_transcript_invalid'),'confidence'=>(float)($x['confidence']??0)]:throw new MeetingException('meeting_transcript_invalid'),$value);}
    /** @return list<array<string,mixed>> */
    private function minutes(mixed $value):array{if(!is_array($value)||$value===[])throw new MeetingException('meeting_minutes_required');return array_map(fn($x)=>is_array($x)?['type'=>$this->text($x['type']??null,40,'meeting_minutes_invalid'),'text'=>$this->text($x['text']??null,4000,'meeting_minutes_invalid'),'source'=>$this->text($x['source']??null,100,'meeting_minutes_invalid')]:throw new MeetingException('meeting_minutes_invalid'),$value);}
    /** @return list<array<string,mixed>> */
    private function outcomes(mixed $value):array{if(!is_array($value)||$value===[])throw new MeetingException('meeting_outcomes_required');$out=[];foreach($value as $x){if(!is_array($x))throw new MeetingException('meeting_outcome_invalid');$type=$this->text($x['type']??null,40,'meeting_outcome_invalid');if(!in_array($type,['decision','action'],true))throw new MeetingException('meeting_outcome_invalid');$out[]=['type'=>$type,'title'=>$this->text($x['title']??null,220,'meeting_outcome_invalid'),'owner'=>$this->text($x['owner']??null,180,'meeting_outcome_invalid'),'due'=>$this->text($x['due']??null,40,'meeting_outcome_invalid'),'destination'=>$this->text($x['destination']??null,80,'meeting_outcome_invalid'),'source'=>$this->text($x['source']??null,100,'meeting_outcome_invalid'),'state'=>'pending'];}return$out;}
    private function assertWriter(string $organisationId,string $userId,string $role):void{if(!in_array($role,['owner','admin','member'],true))throw new MeetingException('meeting_permission_denied');$this->assertMember($organisationId,$userId);}
    private function assertMember(string $organisationId,string $userId):void{$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:organisation_id) AND user_id=UNHEX(:user_id) AND status='active'");$s->execute(['organisation_id'=>$organisationId,'user_id'=>$userId]);if($s->fetchColumn()===false)throw new MeetingException('meeting_not_found');}
    private function id(mixed $value,string $reason):string{if(!is_string($value)||preg_match('/\A[a-f0-9]{32}\z/i',$value)!==1)throw new MeetingException($reason);return strtolower($value);}
    private function text(mixed $value,int $max,string $reason):string{$value=is_string($value)?trim($value):'';if($value===''||mb_strlen($value)>$max)throw new MeetingException($reason);return$value;}
    /** @param array<string,mixed>|list<mixed> $value */
    private function json(array $value):string{return json_encode($value,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
}
